//! Finite moving-chamber interventions using the same field, adapter, and body owners as the lab.
use serde::Serialize;
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use sim::{
    chamber::Chamber,
    environment::*,
    field_lab::{fixture, source_position, FieldScenario},
    sensory::CuePathway,
    Brain, Graph,
};
use std::{sync::Arc, time::Instant};

const SEEDS: std::ops::Range<u64> = 0..30;
const WARMUP: usize = 60;
const MEASURE: usize = 300;
#[derive(Clone, Serialize)]
#[serde(rename_all = "camelCase")]
struct Observation {
    turn: f64,
    flight_turn: f64,
    heading_change: f64,
    final_x: f64,
    final_z: f64,
    final_heading: f64,
    initial_distances: [f64; 2],
    minimum_distances: [f64; 2],
    early_heading_integral: f64,
    early_alignments: [f64; 2],
    mean_odor_difference: f64,
    mean_brightness_difference: f64,
    active_current_ticks: usize,
    last_active_tick: Option<usize>,
}
impl Observation {
    fn metrics(&self, mirror: f64) -> [f64; 8] {
        let side = if mirror > 0.0 { 0 } else { 1 };
        let source = source_position(mirror);
        let dx = source.x - self.final_x;
        let dz = source.z - self.final_z;
        let distance = dx.hypot(dz);
        [
            self.turn,
            self.flight_turn,
            -mirror * self.heading_change,
            self.initial_distances[side] - distance,
            if distance == 0.0 {
                1.0
            } else {
                (dx * self.final_heading.cos() + dz * self.final_heading.sin()) / distance
            },
            self.initial_distances[side] - self.minimum_distances[side],
            -mirror * self.early_heading_integral,
            self.early_alignments[side],
        ]
    }
}
fn run(
    graph: &Arc<Graph>,
    seed: u64,
    fields: FieldSet,
    cue: CuePathway,
    silence: &[u32],
) -> Result<Observation, String> {
    let mut chamber = Chamber::with_fields(
        graph.clone(),
        Brain::seed_for_fly(seed, 0),
        fields,
        Some((cue, 1.0)),
    );
    // Warm the brain alone, keeping every body at the identical source-relative pose.
    for _ in 0..WARMUP {
        chamber.brain.step();
    }
    chamber.brain.set_silenced_neurons(silence)?;
    let initial = chamber.info().initial_pose;
    let initial_distances = [1.0, -1.0].map(|mirror| {
        let p = source_position(mirror);
        (p.x - initial.x).hypot(p.z - initial.z)
    });
    let mut out = Observation {
        turn: 0.,
        flight_turn: 0.,
        heading_change: 0.,
        final_x: initial.x,
        final_z: initial.z,
        final_heading: initial.heading,
        initial_distances,
        minimum_distances: initial_distances,
        early_heading_integral: 0.0,
        early_alignments: [0.0; 2],
        mean_odor_difference: 0.,
        mean_brightness_difference: 0.,
        active_current_ticks: 0,
        last_active_tick: None,
    };
    for tick in 0..MEASURE {
        let frame = chamber.step()?;
        if chamber.brain.external_current().iter().any(|&v| v != 0.0) {
            out.active_current_ticks += 1;
            out.last_active_tick = Some(tick);
        }
        out.turn += frame.neural.motor.turn / MEASURE as f64;
        out.flight_turn += frame.neural.motor.flight_turn / MEASURE as f64;
        out.heading_change += frame.neural.motor.turn * 0.1 * 8.0;
        out.final_x = frame.pose.x;
        out.final_z = frame.pose.z;
        out.final_heading = frame.pose.heading;
        for (side, mirror) in [1.0, -1.0].into_iter().enumerate() {
            let source = source_position(mirror);
            let dx = source.x - frame.pose.x;
            let dz = source.z - frame.pose.z;
            let distance = dx.hypot(dz);
            out.minimum_distances[side] = out.minimum_distances[side].min(distance);
            if tick < 60 {
                out.early_alignments[side] += if distance == 0.0 {
                    1.0 / 60.0
                } else {
                    (dx * frame.pose.heading.cos() + dz * frame.pose.heading.sin())
                        / distance
                        / 60.0
                };
            }
        }
        if tick < 60 {
            out.early_heading_integral += out.heading_change * 0.1;
        }
        out.mean_odor_difference +=
            (frame.sensory.left.odor - frame.sensory.right.odor) / MEASURE as f64;
        out.mean_brightness_difference +=
            (frame.sensory.left.brightness - frame.sensory.right.brightness) / MEASURE as f64;
    }
    Ok(out)
}
fn uniform_fields() -> Result<FieldSet, String> {
    let (fields, _) = fixture(FieldScenario::Lamp, 1.0)?;
    FieldSet::new(
        fields.geometry().clone(),
        FieldConfig {
            baseline_brightness: 0.2,
            ..FieldConfig::default()
        },
        vec![],
        None,
    )
}
fn stats(samples: &[[f64; 8]]) -> Value {
    ["turn","flightTurn","headingTowardSource","distanceReduction","finalAlignmentTowardSource","minimumDistanceReduction","earlyHeadingIntegralTowardSource","earlyAlignmentTowardSource"].into_iter().enumerate().map(|(axis,name)| {
        let n=samples.len() as f64;
        let mean=samples.iter().map(|s|s[axis]).sum::<f64>()/n;
        let sd=(samples.iter().map(|s|(s[axis]-mean).powi(2)).sum::<f64>()/(n-1.0)).sqrt();
        let half=2.045229642*sd/n.sqrt();
        (name.to_string(),json!({"mean":mean,"ci95":[mean-half,mean+half],"positiveSeeds":samples.iter().filter(|s|s[axis]>0.0).count(),"negativeSeeds":samples.iter().filter(|s|s[axis]<0.0).count()}))
    }).collect()
}
fn contrast(a: &[Observation], b: &[Observation], mirror: f64) -> Value {
    stats(
        &a.iter()
            .zip(b)
            .map(|(a, b)| {
                let a = a.metrics(mirror);
                let b = b.metrics(mirror);
                std::array::from_fn(|i| a[i] - b[i])
            })
            .collect::<Vec<_>>(),
    )
}
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().collect();
    let path = args
        .get(1)
